int maxMeetings(vector<pair<int, int>> a) {
    sort(a.begin(), a.end(), [](auto& x, auto& y) {
        return x.second < y.second;      // earliest end first
    });
    int cnt = 0, last = INT_MIN;
    for (auto& [s, e] : a)
        if (s >= last) { cnt++; last = e; }   // fits? take it
    return cnt;
}
